description:
```
// binary file write
FileHandle fileW = FileIO.OpenFile("$profile:file.bin", FileMode.WRITE);
if (fileW)
{
    int valInt = 4679;
    float valFloat = 87.79;
    string valStr = "Hello";
    fileW.Write(valInt);
    fileW.Write(valFloat);
    fileW.Write(valStr);
    fileW.Close();
}

// binary file read
FileHandle fileR = FileIO.OpenFile("$profile:file.bin", FileMode.READ);
if (fileR)
{
    int valInt;
    float valFloat;
    string valStr;
    fileR.Read(valInt, 4);
    fileR.Read(valFloat, 4);
    fileR.Read(valStr, 5);
    fileR.Close();

    Print(valInt);
    Print(valFloat);
    Print(valStr);
}

// text file write
FileHandle textFileW = FileIO.OpenFile("$profile:file.txt", FileMode.WRITE);
if (textFileW)
{
    for (int i = 0; i < 10; i++)
    {
        textFileW.WriteLine("Line " + i);
    }
    textFileW.Close();
}

// text file read
FileHandle textFileR = FileIO.OpenFile("$profile:file.txt", FileMode.READ);
if (textFileR)
{
    string line;
    while(textFileR.ReadLine(line) >= 0)
    {
        Print(line);
    }
    textFileR.Close();
}
```

