    {
        file.Write(10);
        file.Write("lalala");
        file.Write(names);
        file.Close();
    }
}

void TestLoad()
{
    FileSerializer file = new FileSerializer();
    int intVal;
    string stringVal;
    string names[3];

    if (file.Open("test.save", FileMode.READ))
    {
        file.Read(intVal);
        file.Read(stringVal);
        file.Read(names);
        file.Close();
    }
}
```

